static const size_t symbols_cod2mp_s_count = sizeof(symbols_cod2mp_s) / sizeof(symbols_cod2mp_s[0]);

// Returns the Cod2mpSymbol entry whose range contains 'addr', or nullptr.
static inline const Cod2mpSymbol* symbols_cod2mp_s_find(uint32_t addr)
{
    int lo = 0;
    int hi = (int)symbols_cod2mp_s_count - 1;

    while (lo <= hi)
    {
        int mid = lo + (hi - lo) / 2;
        const Cod2mpSymbol& f = symbols_cod2mp_s[mid];

        if (addr < f.addr)
            hi = mid - 1;
        else if (addr >= f.addr + f.len)
            lo = mid + 1;
        else
            return &symbols_cod2mp_s[mid];
    }
    return nullptr;
}

// Returns the symbol name if 'addr' falls within a known function's range,
// or nullptr if not found.
static inline const char* symbols_cod2mp_s_getName(uint32_t addr)
{
    const Cod2mpSymbol* f = symbols_cod2mp_s_find(addr);
    return f ? f->name : nullptr;
}

